-- Fixed round-two feeders for fields divisible by four. Actual placement matches
-- retain NOT NULL entrants; waiting slots live here, off the client write surface.
-- No existing round-two bracket is adopted or regenerated by this migration.
CREATE TABLE public.placement_round_two_slots (
  category_id uuid NOT NULL REFERENCES public.categories(id) ON DELETE CASCADE,
  generation_key text NOT NULL,
  source_a_id uuid NOT NULL REFERENCES public.placement_matches(id) ON DELETE CASCADE,
  source_b_id uuid NOT NULL REFERENCES public.placement_matches(id) ON DELETE CASCADE,
  outcome text NOT NULL CHECK (outcome IN ('winner', 'loser')),
  PRIMARY KEY (category_id, generation_key),
  CHECK (source_a_id <> source_b_id)
);
CREATE INDEX placement_round_two_slots_source_a ON public.placement_round_two_slots(source_a_id);
CREATE INDEX placement_round_two_slots_source_b ON public.placement_round_two_slots(source_b_id);
ALTER TABLE public.placement_round_two_slots ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.placement_round_two_slots FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.placement_round_two_slots TO service_role;
-- The app already writes placement through transactional RPCs. Closing direct writes
-- prevents row-lock-first edits/deletes from bypassing the feeder/reset protocol.
REVOKE INSERT, UPDATE, DELETE ON public.placement_matches FROM authenticated, anon, PUBLIC;

CREATE OR REPLACE FUNCTION public.open_ready_placement_round_two(p_category_id uuid)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_tournament uuid := public.tournament_of_category(p_category_id);
  v_count integer;
  v_sources uuid[];
  v_half integer;
  v_i integer;
  v_inserted integer;
BEGIN
  IF NOT public.can_edit_tournament(v_tournament) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  PERFORM public.lock_tournament_lifecycle_shared(v_tournament);
  PERFORM public.assert_tournament_live(v_tournament);
  -- Match all live writers' lock order. Repeated and concurrent calls append only.
  PERFORM pg_advisory_xact_lock(hashtext('live-schedule'));
  PERFORM pg_advisory_xact_lock(hashtext('placement:' || p_category_id::text));

  IF EXISTS (SELECT 1 FROM public.tier_draws WHERE category_id = p_category_id) THEN
    RETURN 0;
  END IF;
  SELECT count(*) INTO v_count FROM public.placement_entrants
  WHERE category_id = p_category_id AND NOT excluded;
  IF v_count < 4 OR v_count % 4 <> 0 THEN RETURN 0; END IF;
  IF EXISTS (SELECT 1 FROM public.placement_entrants
    WHERE category_id = p_category_id AND NOT excluded AND seed IS NULL) THEN
    RAISE EXCEPTION 'Lock the seed order before generating placement matches';
  END IF;

  -- Leave a pre-existing, batch-generated round two unchanged, including its IDs/times.
  IF NOT EXISTS (SELECT 1 FROM public.placement_round_two_slots WHERE category_id = p_category_id)
     AND EXISTS (SELECT 1 FROM public.placement_matches WHERE category_id = p_category_id AND stage = 'round2') THEN
    RETURN 0;
  END IF;

  SELECT array_agg(id ORDER BY generation_key COLLATE "C") INTO v_sources
  FROM public.placement_matches WHERE category_id = p_category_id AND stage = 'round1';
  IF COALESCE(array_length(v_sources, 1), 0) * 2 <> v_count THEN RETURN 0; END IF;
  -- Each active entrant must appear exactly once; voids cannot become feeder winners.
  IF EXISTS (
    SELECT 1 FROM public.placement_matches m
    JOIN public.placement_entrants a ON a.id = m.entrant_a_id
    JOIN public.placement_entrants b ON b.id = m.entrant_b_id
    WHERE m.id = ANY(v_sources) AND
      (m.status = 'void' OR a.excluded OR b.excluded OR a.category_id <> p_category_id OR b.category_id <> p_category_id)
  ) OR (
    SELECT count(DISTINCT e) FROM public.placement_matches m
    CROSS JOIN LATERAL unnest(ARRAY[m.entrant_a_id, m.entrant_b_id]) e
    WHERE m.id = ANY(v_sources)
  ) <> v_count THEN RETURN 0; END IF;

  v_half := v_count / 4;
  FOR v_i IN 1..v_half LOOP
    INSERT INTO public.placement_round_two_slots
      (category_id, generation_key, source_a_id, source_b_id, outcome)
    VALUES
      (p_category_id, 'r2-' || v_i, v_sources[v_i], v_sources[v_i + v_half], 'winner'),
      (p_category_id, 'r2-' || (v_i + v_half), v_sources[v_i], v_sources[v_i + v_half], 'loser')
    ON CONFLICT (category_id, generation_key) DO NOTHING;
  END LOOP;

  INSERT INTO public.placement_matches
    (tournament_id, category_id, stage, generation_key, entrant_a_id, entrant_b_id, prerequisite_ids)
  SELECT v_tournament, p_category_id, 'round2', s.generation_key,
    CASE WHEN s.outcome = 'winner' THEN a.winner_id
      WHEN a.winner_id = a.entrant_a_id THEN a.entrant_b_id ELSE a.entrant_a_id END,
    CASE WHEN s.outcome = 'winner' THEN b.winner_id
      WHEN b.winner_id = b.entrant_a_id THEN b.entrant_b_id ELSE b.entrant_a_id END,
    ARRAY[a.id, b.id]
  FROM public.placement_round_two_slots s
  JOIN public.placement_matches a ON a.id = s.source_a_id
  JOIN public.placement_matches b ON b.id = s.source_b_id
  WHERE s.category_id = p_category_id
    AND a.status IN ('reported', 'walkover') AND a.winner_id IS NOT NULL
    AND b.status IN ('reported', 'walkover') AND b.winner_id IS NOT NULL
  ON CONFLICT (category_id, generation_key) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted;
END;
$$;
REVOKE ALL ON FUNCTION public.open_ready_placement_round_two(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.open_ready_placement_round_two(uuid) TO authenticated;

-- Managed sources are authoritative even for direct table writes and stale clients.
-- Corrections retract only unplayed children. Once a child starts, its sources are locked.
CREATE OR REPLACE FUNCTION public.guard_incremental_placement()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_slot public.placement_round_two_slots;
  v_a public.placement_matches;
  v_b public.placement_matches;
  v_expected_a uuid;
  v_expected_b uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND (
    EXISTS (SELECT 1 FROM public.placement_round_two_slots WHERE category_id = OLD.category_id)
    OR EXISTS (SELECT 1 FROM public.placement_round_two_slots WHERE category_id = NEW.category_id)
  ) AND (NEW.category_id <> OLD.category_id OR NEW.tournament_id <> OLD.tournament_id
    OR NEW.stage <> OLD.stage OR NEW.generation_key <> OLD.generation_key
    OR NEW.entrant_a_id <> OLD.entrant_a_id OR NEW.entrant_b_id <> OLD.entrant_b_id) THEN
    RAISE EXCEPTION 'Reset the placement schedule before changing a feeder pairing';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.placement_round_two_slots WHERE category_id = NEW.category_id) THEN
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('live-schedule'));
  PERFORM pg_advisory_xact_lock(hashtext('placement:' || NEW.category_id::text));

  IF TG_OP = 'UPDATE' THEN
    IF NEW.category_id IS DISTINCT FROM OLD.category_id OR NEW.stage <> OLD.stage
       OR NEW.generation_key <> OLD.generation_key
       OR NEW.entrant_a_id <> OLD.entrant_a_id OR NEW.entrant_b_id <> OLD.entrant_b_id THEN
      RAISE EXCEPTION 'Reset the placement schedule before changing a feeder pairing';
    END IF;
    IF NEW.winner_id IS DISTINCT FROM OLD.winner_id
       OR (OLD.status IN ('reported', 'walkover') AND NEW.status NOT IN ('reported', 'walkover')) THEN
      IF EXISTS (SELECT 1 FROM public.tier_draws WHERE category_id = NEW.category_id) THEN
        RAISE EXCEPTION 'Knockout draws depend on this placement result';
      END IF;
      IF NEW.stage = 'round1' THEN
        IF EXISTS (
          SELECT 1 FROM public.placement_round_two_slots s
          JOIN public.placement_matches c ON c.category_id = s.category_id AND c.generation_key = s.generation_key
          WHERE (s.source_a_id = OLD.id OR s.source_b_id = OLD.id)
            AND (c.status <> 'scheduled' OR c.started_at IS NOT NULL)
        ) THEN RAISE EXCEPTION 'A dependent round two match has already started'; END IF;
        DELETE FROM public.placement_matches c USING public.placement_round_two_slots s
        WHERE c.category_id = s.category_id AND c.generation_key = s.generation_key
          AND (s.source_a_id = OLD.id OR s.source_b_id = OLD.id);
      END IF;
    END IF;
  END IF;

  IF NEW.stage = 'round2' THEN
    SELECT * INTO v_slot FROM public.placement_round_two_slots
    WHERE category_id = NEW.category_id AND generation_key = NEW.generation_key;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unknown round two feeder slot'; END IF;
    SELECT * INTO v_a FROM public.placement_matches WHERE id = v_slot.source_a_id;
    SELECT * INTO v_b FROM public.placement_matches WHERE id = v_slot.source_b_id;
    IF v_a.status NOT IN ('reported', 'walkover') OR v_b.status NOT IN ('reported', 'walkover')
       OR v_a.winner_id IS NULL OR v_b.winner_id IS NULL THEN
      RAISE EXCEPTION 'Both round one sources must have a decided winner';
    END IF;
    v_expected_a := CASE WHEN v_slot.outcome = 'winner' THEN v_a.winner_id
      WHEN v_a.winner_id = v_a.entrant_a_id THEN v_a.entrant_b_id ELSE v_a.entrant_a_id END;
    v_expected_b := CASE WHEN v_slot.outcome = 'winner' THEN v_b.winner_id
      WHEN v_b.winner_id = v_b.entrant_a_id THEN v_b.entrant_b_id ELSE v_b.entrant_a_id END;
    IF NEW.entrant_a_id <> v_expected_a OR NEW.entrant_b_id <> v_expected_b
       OR NEW.tournament_id <> v_a.tournament_id OR NEW.is_makeup OR NEW.is_crossover THEN
      RAISE EXCEPTION 'Round two entrants must match their feeder results';
    END IF;
    NEW.prerequisite_ids := ARRAY[v_a.id, v_b.id];
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.guard_incremental_placement() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER placement_matches_incremental
BEFORE INSERT OR UPDATE ON public.placement_matches
FOR EACH ROW EXECUTE FUNCTION public.guard_incremental_placement();

-- Retain the whole-category correction guard for legacy/adaptive round twos only.
CREATE OR REPLACE FUNCTION public.guard_placement_correction()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
BEGIN
  IF NEW.stage = 'round1'
     AND NOT EXISTS (SELECT 1 FROM public.placement_round_two_slots WHERE category_id = NEW.category_id)
     AND EXISTS (SELECT 1 FROM public.placement_matches WHERE category_id = NEW.category_id AND stage = 'round2') THEN
    RAISE EXCEPTION 'Round two was built from this result — regenerate round two to change the winner';
  END IF;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.guard_placement_correction() FROM PUBLIC, anon, authenticated;

-- Preserve the existing RPCs and their legacy paths; managed feeders use the trigger above.
CREATE OR REPLACE FUNCTION public.reset_placement_result(p_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_category uuid;
  v_stage text;
DECLARE
  v_tournament uuid;
BEGIN
  -- The tournament is not a parameter, so it is resolved from the id that is.
  v_tournament := public.tournament_of_placement_match(p_match_id);
  IF NOT public.can_edit_tournament(v_tournament) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  PERFORM public.assert_tournament_live(v_tournament);

  SELECT category_id, stage INTO v_category, v_stage
  FROM public.placement_matches WHERE id = p_match_id;
  IF v_category IS NULL THEN
    RAISE EXCEPTION 'Unknown match';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('live-schedule'));
  PERFORM pg_advisory_xact_lock(hashtext('placement:' || v_category::text));

  -- Adaptive and legacy pairings still depend on the full winner/loser sets.
  -- Managed sources are instead protected/retracted by the BEFORE trigger.
  IF v_stage = 'round1' AND NOT EXISTS (
    SELECT 1 FROM public.placement_round_two_slots WHERE category_id = v_category
  ) AND EXISTS (
    SELECT 1 FROM public.placement_matches
    WHERE category_id = v_category AND stage = 'round2'
  ) THEN
    RAISE EXCEPTION 'Round two was built from this result — regenerate round two instead';
  END IF;

  UPDATE public.placement_matches
  SET games = '[]'::jsonb,
      winner_id = NULL,
      status = 'scheduled',
      reported_time = NULL,
      -- The fix: without this, a restart inherits the original start time.
      started_at = NULL,
      ended_at = NULL
  WHERE id = p_match_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.apply_placement_round_two(p_category_id uuid, p_matches jsonb, p_force boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tournament uuid;
  v_expected int;
  v_inserted int;
  v_row jsonb;
BEGIN
  -- The tournament is not a parameter, so it is resolved from the id that is.
  v_tournament := public.tournament_of_category(p_category_id);
  IF NOT public.can_edit_tournament(v_tournament) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  PERFORM public.assert_tournament_live(v_tournament);

  SELECT tournament_id INTO v_tournament FROM public.categories WHERE id = p_category_id;
  IF v_tournament IS NULL THEN
    RAISE EXCEPTION 'Unknown category';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('placement:' || p_category_id::text));

  IF EXISTS (SELECT 1 FROM public.placement_round_two_slots WHERE category_id = p_category_id) THEN
    RAISE EXCEPTION 'Round two uses fixed feeders; reset the placement schedule to regenerate';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.placement_matches
    WHERE category_id = p_category_id
      AND stage = 'round1'
      AND (status NOT IN ('reported', 'walkover') OR winner_id IS NULL)
  ) THEN
    RAISE EXCEPTION 'Round two needs every round one result first';
  END IF;

  IF NOT p_force AND EXISTS (
    SELECT 1 FROM public.placement_matches
    WHERE category_id = p_category_id AND stage = 'round2' AND status <> 'scheduled'
  ) THEN
    RAISE EXCEPTION 'Round two has already been played for this category';
  END IF;

  DELETE FROM public.placement_matches
  WHERE category_id = p_category_id AND stage = 'round2';

  INSERT INTO public.placement_matches (
    tournament_id, category_id, stage, generation_key,
    entrant_a_id, entrant_b_id, is_makeup, is_crossover
  )
  SELECT
    v_tournament,
    p_category_id,
    'round2',
    item->>'key',
    a.id,
    b.id,
    COALESCE((item->>'is_makeup')::boolean, false),
    COALESCE((item->>'is_crossover')::boolean, false)
  FROM jsonb_array_elements(COALESCE(p_matches, '[]'::jsonb)) AS item
  JOIN public.placement_entrants a
    ON a.category_id = p_category_id AND a.team_id = (item->>'entrant_a_team_id')::uuid
  JOIN public.placement_entrants b
    ON b.category_id = p_category_id AND b.team_id = (item->>'entrant_b_team_id')::uuid;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  v_expected := jsonb_array_length(COALESCE(p_matches, '[]'::jsonb));
  IF v_inserted <> v_expected THEN
    RAISE EXCEPTION 'Expected to create % matches but created % — an entrant is missing',
      v_expected, v_inserted;
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(COALESCE(p_matches, '[]'::jsonb))
  LOOP
    IF jsonb_typeof(v_row->'prerequisite_keys') = 'array'
       AND jsonb_array_length(v_row->'prerequisite_keys') > 0 THEN
      UPDATE public.placement_matches m
      SET prerequisite_ids = (
        SELECT COALESCE(array_agg(dep.id), '{}')
        FROM jsonb_array_elements_text(v_row->'prerequisite_keys') AS k(key)
        JOIN public.placement_matches dep
          ON dep.category_id = p_category_id AND dep.generation_key = k.key
      )
      WHERE m.category_id = p_category_id AND m.generation_key = v_row->>'key';
    END IF;
  END LOOP;

  RETURN v_inserted;
END;
$function$;
CREATE OR REPLACE FUNCTION public.report_placement_result(
  p_match_id uuid,
  p_games jsonb,
  p_ended_minutes_ago integer DEFAULT 0
)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  -- The most a finish may be backdated. Twelve hours covers the honest worst case - a
  -- result entered at close for a match that finished that morning - while still
  -- refusing a typo like 7000, whose resolved finish would land before the fixture's
  -- own day and reflow the schedule from a time that never existed. Named rather than
  -- inlined so the ceiling is one edit, and mirrored by MAX_ENDED_MINUTES_AGO in
  -- src/lib/tournament/placement-actions.ts so the desk refuses the same number.
  c_max_minutes_ago constant integer := 720;
  v_tournament uuid;
  v_side text;
  v_winner uuid;
  v_started_at timestamptz;
  v_ended_at timestamptz;
BEGIN
  -- The tournament is not a parameter, so it is resolved from the id that is.
  v_tournament := public.tournament_of_placement_match(p_match_id);
  IF NOT public.can_edit_tournament(v_tournament) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  PERFORM public.assert_tournament_live(v_tournament);

  -- Input before data: a negative offset would resolve a finish in the future.
  IF p_ended_minutes_ago < 0 THEN
    RAISE EXCEPTION 'A finish time cannot be in the future';
  END IF;
  IF p_ended_minutes_ago > c_max_minutes_ago THEN
    RAISE EXCEPTION 'A finish more than % minutes ago cannot be recorded', c_max_minutes_ago;
  END IF;

  SELECT tournament_id INTO v_tournament
  FROM public.placement_matches WHERE id = p_match_id;
  IF v_tournament IS NULL THEN
    RAISE EXCEPTION 'Unknown match';
  END IF;

  SELECT public.placement_check_games(
    p_games, t.placement_games_to, t.placement_win_by, t.placement_best_of
  ) INTO v_side
  FROM public.tournaments t WHERE t.id = v_tournament;

  SELECT CASE WHEN v_side = 'a' THEN entrant_a_id ELSE entrant_b_id END,
         started_at
    INTO v_winner, v_started_at
  FROM public.placement_matches WHERE id = p_match_id;
  IF v_winner IS NULL THEN
    RAISE EXCEPTION 'That side has no entrant assigned yet';
  END IF;

  -- Resolve the finish. A non-zero offset is an explicit "this ended N minutes ago"
  -- and overrides whatever is stored; zero keeps the old COALESCE, so a fixture that
  -- preset ended_at is still respected rather than replaced with the wall clock.
  IF p_ended_minutes_ago > 0 THEN
    v_ended_at := statement_timestamp() - make_interval(mins => p_ended_minutes_ago);
  ELSE
    SELECT COALESCE(ended_at, statement_timestamp()) INTO v_ended_at
    FROM public.placement_matches WHERE id = p_match_id;
  END IF;

  -- A finish before the match started describes no real span, and would feed the
  -- reflow a negative duration. Only checked when the match has a start: a result
  -- reported without ever starting has no window to be inside.
  IF v_started_at IS NOT NULL AND v_ended_at < v_started_at THEN
    RAISE EXCEPTION 'The finish time is before the match started';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('live-schedule'));
  PERFORM pg_advisory_xact_lock(hashtext('placement:' || (SELECT category_id FROM public.placement_matches WHERE id = p_match_id)::text));

  UPDATE public.placement_matches
  SET games = p_games,
      winner_id = v_winner,
      status = 'reported',
      reported_time = statement_timestamp(),
      ended_at = v_ended_at
  WHERE id = p_match_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'That match was withdrawn by a source correction; refresh the match list';
  END IF;

  PERFORM public.shift_live_schedule_after_match('placement_matches', p_match_id);
END;
$function$;
REVOKE ALL ON FUNCTION public.reset_placement_result(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reset_placement_result(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.apply_placement_round_two(uuid, jsonb, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.apply_placement_round_two(uuid, jsonb, boolean) TO authenticated;
REVOKE ALL ON FUNCTION public.report_placement_result(uuid, jsonb, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.report_placement_result(uuid, jsonb, integer) TO authenticated;

DO $verify$
BEGIN
  IF has_table_privilege('authenticated', 'public.placement_round_two_slots', 'INSERT')
     OR has_table_privilege('authenticated', 'public.placement_round_two_slots', 'SELECT')
     OR has_table_privilege('authenticated', 'public.placement_matches', 'UPDATE')
     OR has_table_privilege('authenticated', 'public.placement_matches', 'DELETE')
     OR has_function_privilege('anon', 'public.open_ready_placement_round_two(uuid)', 'EXECUTE') THEN
    RAISE EXCEPTION 'Incremental placement grants are not closed';
  END IF;
END;
$verify$;
NOTIFY pgrst, 'reload schema';
